"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5972],{32257:e=>{e.exports=JSON.parse('{"functions":[{"name":"newWorldSeed","desc":"Draws a fresh world seed. Called once by the `bootstrap` system.","params":[],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":33,"path":"src/main/server/helpers/seed.luau"}},{"name":"chunkKey","desc":"The `\\"x,y\\"` key a chunk is stored under.","params":[{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":45,"path":"src/main/server/helpers/seed.luau"}},{"name":"chunkSeed","desc":"Hashes a chunk\'s coordinates against the world seed.\\n\\nThe two multipliers are large odd constants \u2014 the same ones Knuth-style\\ninteger hashes use \u2014 chosen so that adjacent chunks, whose coordinates differ\\nby one, land far apart in the output. The final xor-shift mixes the high bits\\nback down, otherwise nearby chunks share low-bit structure and their mazes\\ncome out visibly similar.\\n\\nThe rotate between the two coordinate terms is load-bearing. Folding both in\\nwith a single `bxor` puts them at the same bit positions, where negating both\\ncoordinates cancels out and `(x, y)` hashes to the same value as `(-x, -y)` \u2014\\na world point-symmetric about the origin, with 16% of chunks in a 121x121\\nblock sharing a maze with their opposite. Rotating between the terms breaks\\nthe symmetry: the same sweep collides zero times.","params":[{"name":"worldSeed","desc":"","lua_type":"number"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"}],"returns":[{"desc":"Seed for this chunk\'s `Random`.","lua_type":"number"}],"function_type":"static","source":{"line":71,"path":"src/main/server/helpers/seed.luau"}},{"name":"doorOffsets","desc":"The two cell offsets where a chunk border is open.\\n\\nBoth chunks either side of a border call this with the same arguments and get\\nthe same answer, which is what lets independently generated chunks line up.","params":[{"name":"worldSeed","desc":"","lua_type":"number"},{"name":"chunkX","desc":"Chunk column.","lua_type":"number"},{"name":"chunkY","desc":"Chunk row.","lua_type":"number"},{"name":"side","desc":"Which border.","lua_type":"\\"east\\" | \\"north\\""}],"returns":[{"desc":"Two distinct offsets along that border.","lua_type":"{ number }"}],"function_type":"static","source":{"line":91,"path":"src/main/server/helpers/seed.luau"}}],"properties":[{"name":"DOOR_SIDE_SEED","desc":"Per-side salt, so a chunk\'s east and north doorways are not drawn from the\\nsame sequence.","lua_type":"{ [string]: number }","source":{"line":25,"path":"src/main/server/helpers/seed.luau"}}],"types":[],"name":"seed","desc":"Deterministic randomness for worldgen. Every chunk\'s contents are a pure\\nfunction of the world seed and the chunk\'s coordinates, so chunks can be\\ngenerated in any order, unloaded, and regenerated identically.\\n\\nNothing here reads the world. The seed is a parameter, which is also what\\nmakes these functions testable \u2014 feed a fixed seed, get a fixed maze.","tags":["server-helper"],"realm":["Server"],"source":{"line":13,"path":"src/main/server/helpers/seed.luau"}}')}}]);